"""Durable recovery record survives process recreation and rejects malformed/foreign APK metadata."""
from pathlib import Path
import subprocess,tempfile
source=Path('app/src/io/tvos/TizenRecovery.java').read_text()
harness='''package io.tvos;import java.io.*;class Test{static void check(boolean b,String s){if(!b)throw new AssertionError(s);}public static void main(String[] args)throws Exception{File root=new File(args[0]);String hash="aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa";check(TizenRecovery.read(root)==null,"no unsolicited recovery");new TizenRecovery("v1.0.8","https://github.com/reisxd/TizenTubeCobalt/releases/download/v1.0.8/cobalt-arm.apk",hash).write(root);TizenRecovery record=TizenRecovery.read(root);check(record!=null&&record.sha256.equals(hash)&&record.version.equals("v1.0.8"),"selected version remains recoverable after a fresh read");new TizenRecovery("v2.0.2","https://github.com/reisxd/TizenTubeCobalt/releases/download/v2.0.2/cobalt-arm64.apk",hash).write(root);check(TizenRecovery.read(root).version.equals("v2.0.2"),"replacement is complete and atomic");for(String url:new String[]{"https://evil.invalid/file.apk","https://github.com/reisxd/TizenTubeCobalt/releases/download/v9.0.0/cobalt-arm.apk"})try{new TizenRecovery("v1.0.8",url,hash);throw new AssertionError("foreign or mismatched source");}catch(IllegalArgumentException expected){}try(FileOutputStream out=new FileOutputStream(new File(root,"tizen-install.pending"))){out.write(1);}check(TizenRecovery.read(root)==null,"truncated state cannot launch installation");TizenRecovery.clear(root);check(TizenRecovery.read(root)==null,"success/cancellation clears pending recovery");System.out.println("PASS: durable Tizen recovery, atomic replacement, metadata bounds, invalid sources and cleanup");}}'''
with tempfile.TemporaryDirectory() as tmp:
 root=Path(tmp);p=root/'io/tvos';p.mkdir(parents=True);(p/'TizenRecovery.java').write_text(source);(p/'Test.java').write_text(harness)
 subprocess.run(['java','com.sun.tools.javac.Main','--release','8','-Xlint:all','-Werror','-d',tmp,*map(str,p.glob('*.java'))],check=True)
 subprocess.run(['java','-cp',tmp,'io.tvos.Test',tmp],check=True)
